type testing_period = {
  actual_days_present : int; (* physical presence days in the testing period *)
  absence_days_to_credit : int; (* days absent that individual asks to treat as present *)
  testing_period_length : int; (* total days from start of 31-day period through end of election year *)
}

(* (b)(4)(A)(iv)(I): present at least 31 consecutive days in the election year *)
let is_present_31_consecutive_days (days_present_in_31_day_period : int) : bool =
  days_present_in_31_day_period >= 31

(* absence days credited as presence, capped at 5 in the aggregate *)
let effective_days_present (period : testing_period) : int =
  let credited_absence = min period.absence_days_to_credit 5 in
  period.actual_days_present + credited_absence

(* (b)(4)(A)(iv)(II): present >= 75% of the testing period, with up to 5 absent days credited as present *)
let is_present_75_percent_of_testing_period (period : testing_period) : bool =
  float_of_int (effective_days_present period) >=. 0.75 *. float_of_int period.testing_period_length

(* (b)(4)(A)(iv): both the 31-consecutive-day test and the 75%-of-testing-period test must hold *)
let is_present_for_election_year_test (days_present_in_31_day_period : int) (period : testing_period) : bool =
  is_present_31_consecutive_days days_present_in_31_day_period &&
  is_present_75_percent_of_testing_period period
